<script setup lang="ts">import { ref,onMounted } from 'vue';import { api } from '../../api';const props=defineProps<{section?:string}>();const rows=ref<any[]>([]);const message=ref('');const keyword=ref('');async function load(){if(props.section==='docs')rows.value=(await api.adminDocs({keyword:keyword.value})).items;else if(props.section==='review')rows.value=(await api.reviewTasks()).items;else if(props.section==='pathways')rows.value=await api.adminPathways();else if(props.section==='stats'){const s=await api.adminStats();message.value=`文档 ${s.doc_count} · 问答 ${s.qa_count} · 待审核 ${s.review_pending_count}`}}async function action(){if(props.section==='index'){const r=await api.rebuildIndex({scope:'all',incremental:true});message.value=`索引任务 ${r.task_id} 已排队`}else if(props.section==='review'){await load();message.value=`加载 ${rows.value.length} 条审核任务`}else await load()}async function review(id:string){await api.reviewAction(id,{action:'approve',comment:'演示审核'});message.value='已完成演示审核';await load()}onMounted(load)</script><template><section class="content-page"><div class="eyebrow">ADMIN / {{section?.toUpperCase()}}</div><h1>{{section==='docs'?'语料管理':section==='index'?'索引管理':section==='review'?'审核工作台':section==='pathways'?'途径与规则维护':'数据统计'}}</h1><p class="lede">管理端操作保留来源与留痕，当前内容来自 Mock。</p><div class="ask-row" v-if="section==='docs'"><input v-model="keyword" placeholder="按标题或省份筛选" @keyup.enter="load"/><button class="primary" @click="load">筛选 ↗</button></div><div class="hero-actions"><button class="primary" @click="action">{{section==='index'?'重建索引':section==='review'?'刷新审核队列':'刷新数据'}} ↗</button><button v-if="section==='docs'" class="text-btn">上传语料</button></div><div v-if="message" class="state-box">{{message}}</div><div class="admin-table" v-if="rows.length"><div class="table-row table-head"><span>状态</span><span>名称 / 问题</span><span>来源 / 触发原因</span><span>操作</span></div><div v-for="(row,i) in rows" :key="row.task_id||row.doc_id||row.pathway_id||i" class="table-row"><span class="data-status">{{row.status||row.confidence||'演示'}}</span><span>{{row.title||row.question||row.name}}</span><span>{{row.source_name||row.trigger_reason||row.category||'演示数据'}}</span><button v-if="section==='review'" class="link" @click="review(row.task_id)">通过 ↗</button><span v-else class="muted">查看</span></div></div><div v-else class="state-box">暂无数据或尚未加载。</div></section></template>
